class StudentGradeBook:
    def __init__(self):
        self.grade_book = {}

    def add_student(self, name):
        """Adds a new student to the grade book with an empty dictionary for grades."""
        if name not in self.grade_book:
            self.grade_book[name] = {}
            print(f"Student '{name}' added successfully.")
        else:
            print(f"Student '{name}' already exists.")

    def add_grade(self, name, subject, grade):
        """Adds a grade for a specific subject to a student's record."""
        if name in self.grade_book:
            if subject not in self.grade_book[name]:
                self.grade_book[name][subject] = []
            self.grade_book[name][subject].append(grade)
            print(f"Grade for '{subject}' added for student '{name}'.")
        else:
            print(f"Student '{name}' does not exist.")

    def remove_student(self, name):
        """Removes a student's record from the grade book."""
        if name in self.grade_book:
            del self.grade_book[name]
            print(f"Student '{name}' removed successfully.")
        else:
            print(f"Student '{name}' does not exist.")

    def update_grade(self, name, subject, grade):
        """Updates a grade for a specific subject in a student's record."""
        if name in self.grade_book and subject in self.grade_book[name]:
            self.grade_book[name][subject][-1] = grade
            print(f"Grade for '{subject}' updated for student '{name}'.")
        elif name not in self.grade_book:
            print(f"Student '{name}' does not exist.")
        else:
            print(f"Subject '{subject}' does not exist for student '{name}'.")

    def calculate_average(self, name):
        """Calculates the average grade for a student."""
        if name in self.grade_book:
            total_grades = 0
            total_subjects = 0
            for subject, grades in self.grade_book[name].items():
                total_grades += sum(grades)
                total_subjects += len(grades)
            if total_subjects > 0:
                average = total_grades / total_subjects
                print(f"The average grade for student '{name}' is {average:.2f}.")
            else:
                print(f"No grades available for student '{name}'.")
        else:
            print(f"Student '{name}' does not exist.")

    def display_student_grades(self, name):
        """Displays all grades for a student."""
        if name in self.grade_book:
            print(f"Grades for student '{name}':")
            for subject, grades in self.grade_book[name].items():
                print(f"{subject}: {grades}")
        else:
            print(f"Student '{name}' does not exist.")


